source='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    background = Counter(x for row in out for x in row).most_common(1)[0][0]
    pairs = []
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r + 1][nc] == color:
                    pairs.append((r, c, dc, color))
    for r, c, dc, color in pairs:
        # Extend away from both ends of each diagonal pair.
        for rr, cc, dr, stepc in ((r - 1, c - dc, -1, -dc), (r + 2, c + 2 * dc, 1, dc)):
            while 0 <= rr < h and 0 <= cc < w:
                if out[rr][cc] != background and out[rr][cc] != color:
                    break
                out[rr][cc] = color
                rr += dr
                cc += stepc
    return out
'''
